pub fn get_kit_diff(before: &Kit, after: &Kit) -> KitDiff {
    let mut diff = KitDiff {
        guid: before.guid.clone(),
        ..Default::default()
    };
    if before.name != after.name {
        diff.name = Some(after.name.clone());
    }
    if before.version != after.version {
        diff.version = Some(after.version.clone());
    }
    if before.description != after.description {
        diff.description = Some(after.description.clone());
    }
    if before.icon != after.icon {
        diff.icon = Some(after.icon.clone());
    }
    if before.image != after.image {
        diff.image = Some(after.image.clone());
    }
    if before.preview != after.preview {
        diff.preview = Some(after.preview.clone());
    }
    if before.remote != after.remote {
        diff.remote = Some(after.remote.clone());
    }
    if before.homepage != after.homepage {
        diff.homepage = Some(after.homepage.clone());
    }
    if before.license != after.license {
        diff.license = Some(after.license.clone());
    }
    diff.types = get_guid_collection_diff(&before.types, &after.types, "type");
    diff.designs = get_guid_collection_diff(&before.designs, &after.designs, "design");
    diff.tags = get_guid_collection_diff(&before.tags, &after.tags, "tag");
    diff.concepts = get_guid_collection_diff(&before.concepts, &after.concepts, "concept");
    diff.ports = get_guid_collection_diff(&before.ports, &after.ports, "port");
    diff.qualities = get_guid_collection_diff(&before.qualities, &after.qualities, "quality");
    diff.files = get_guid_collection_diff(&before.files, &after.files, "file");
    diff.folders = get_guid_collection_diff(&before.folders, &after.folders, "folder");
    diff.authors = get_guid_collection_diff(&before.authors, &after.authors, "author");
    diff.attributes = get_guid_collection_diff(&before.attributes, &after.attributes, "attribute");
    diff
}

/// Computes the DesignDiff that transforms `before` into `after`.
/// [👤compose📚rs💻compose🔖kitchangehelpers🛠️getdesigndiff](composerepo://p/u/compose/b/l/rs/f/compose.rs/s/Kit%20Change%20Helpers/d/i/get_design_diff)
pub fn get_design_diff(before: &Design, after: &Design) -> DesignDiff {
    let mut diff = DesignDiff {
        guid: before.guid.clone(),
        ..Default::default()
    };
    if before.name != after.name {
        diff.name = Some(after.name.clone());
    }
    if before.parent != after.parent {
        diff.parent = Some(after.parent.clone());
    }
    if before.description != after.description {
