    }
    if before.authors != after.authors {
        diff.authors = Some(after.authors.clone());
    }
    if before.active_layer != after.active_layer {
        diff.active_layer = Some(after.active_layer.clone());
    }
    diff.props = get_guid_collection_diff(&before.props, &after.props, "prop");
    diff.pieces = get_guid_collection_diff(&before.pieces, &after.pieces, "piece");
    diff.connections = get_guid_collection_diff(&before.connections, &after.connections, "connection");
