pub fn get_design_change(before: &Design, after: &Design) -> DesignChange {
    let forward = get_design_diff(before, after);
    let backward = inverse_design_diff(before, &forward);
    DesignChange {
        forward,
        backward,
        author: None,
        time: None,
        before: Some(before.clone()),
        after: Some(after.clone()),
    }
}

