/// Computes a JSON-level object diff: returns a JSON object containing only the fields
/// from `after` that differ from `before`. Fields present in `before` but missing in `after`
/// are included as null. Fields that are equal are omitted.
/// [👤compose📚rs💻compose🔖kitchangehelpers🛠️jsonobjectdiff](composerepo://p/u/compose/b/l/rs/f/compose.rs/s/Kit%20Change%20Helpers/d/i/json_object_diff)
fn json_object_diff(before: &serde_json::Value, after: &serde_json::Value) -> serde_json::Value {
    use serde_json::Value;
    match (before, after) {
        (Value::Object(b), Value::Object(a)) => {
            let mut result = serde_json::Map::new();
            for (key, a_val) in a {
                match b.get(key) {
                    Some(b_val) if b_val == a_val => {}
                    _ => {
                        result.insert(key.clone(), a_val.clone());
                    }
                }
            }
            for (key, _) in b {
                if !a.contains_key(key) {
                    result.insert(key.clone(), Value::Null);
                }
            }
            Value::Object(result)
        }
        _ if before == after => Value::Object(serde_json::Map::new()),
        _ => after.clone(),
    }
}

/// Computes a CollectionDiff between two optional collections of guid-identified items.
/// Added = items in `after` not found in `before` by guid.
/// Removed = items in `before` not found in `after` by guid.
/// Updated = items present in both (by guid) but with different content; sub-diffs are computed via JSON.
/// [👤compose📚rs💻compose🔖kitchangehelpers🛠️getguidcollectiondiff](composerepo://p/u/compose/b/l/rs/f/compose.rs/s/Kit%20Change%20Helpers/d/i/get_guid_collection_diff)
fn get_guid_collection_diff<T, D>(
    before: &Option<Vec<T>>,
    after: &Option<Vec<T>>,
    entity_key: &str,
) -> Option<CollectionDiff<T, D>>
where
    T: HasGuid + Clone + Serialize + PartialEq,
    D: DiffHasGuid + serde::de::DeserializeOwned,
{
    let before_items = before.as_ref().map(|v| v.as_slice()).unwrap_or(&[]);
    let after_items = after.as_ref().map(|v| v.as_slice()).unwrap_or(&[]);

    let before_map: HashMap<String, &T> = before_items
        .iter()
        .map(|i| (i.guid().to_string(), i))
        .collect();
    let after_map: HashMap<String, &T> = after_items
        .iter()
        .map(|i| (i.guid().to_string(), i))
        .collect();

    let mut added = Vec::new();
    let mut removed = Vec::new();
    let mut updated = Vec::new();

    for item in after_items {
        if !before_map.contains_key(item.guid()) {
            added.push(item.clone());
        }
    }

    for item in before_items {
        if !after_map.contains_key(item.guid()) {
            removed.push(RemovedItem {
                guid: item.guid().to_string(),
            });
        }
    }

    for item in after_items {
        if let Some(before_item) = before_map.get(item.guid()) {
            if *before_item != item {
                let before_val = serde_json::to_value(before_item).unwrap_or_default();
                let after_val = serde_json::to_value(item).unwrap_or_default();
                let mut diff_val = json_object_diff(&before_val, &after_val);
                if let serde_json::Value::Object(ref mut map) = diff_val {
                    map.insert(
                        "guid".to_string(),
                        serde_json::Value::String(item.guid().to_string()),
                    );
                }
                if let Ok(diff) = serde_json::from_value::<D>(diff_val) {
                    updated.push(DiffUpdate {
                        key: entity_key.to_string(),
                        guid: item.guid().to_string(),
                        diff,
                    });
                }
            }
        }
    }

    if added.is_empty() && removed.is_empty() && updated.is_empty() {
        None
    } else {
        Some(CollectionDiff {
            added: if added.is_empty() { None } else { Some(added) },
            removed: if removed.is_empty() {
                None
            } else {
                Some(removed)
            },
            updated: if updated.is_empty() {
                None
            } else {
                Some(updated)
            },
        })
    }
}

/// Computes the KitDiff that transforms `before` into `after`.
/// [👤compose📚rs💻compose🔖kitchangehelpers🛠️getkitdiff](composerepo://p/u/compose/b/l/rs/f/compose.rs/s/Kit%20Change%20Helpers/d/i/get_kit_diff)
