                for (_, val) in map.iter_mut() {
                    normalize_json(val);
                }
            }
            _ => {}
        }
    }
    match (serde_json::to_value(a), serde_json::to_value(b)) {
        (Ok(mut va), Ok(mut vb)) => {
            normalize_json(&mut va);
            normalize_json(&mut vb);
            va == vb
        }
        _ => false,
    }
}

